<?php
require_once 'config.php';require_once 'includes/functions.php';require_user();$uid=current_user_id();
if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);$title=trim($_POST['judul_catatan']??'');$body=trim($_POST['isi_catatan']??'');if($title===''||$body===''){flash('Judul dan isi catatan wajib diisi.','error');}else{if($id){$s=$pdo->prepare('UPDATE notes SET judul_catatan=?,isi_catatan=? WHERE id=? AND user_id=?');$s->execute([$title,$body,$id,$uid]);}else{$s=$pdo->prepare('INSERT INTO notes(user_id,judul_catatan,isi_catatan) VALUES(?,?,?)');$s->execute([$uid,$title,$body]);}flash('Catatan berhasil disimpan.');}header('Location: notes.php');exit;}
if(isset($_GET['delete'])){$s=$pdo->prepare('DELETE FROM notes WHERE id=? AND user_id=?');$s->execute([(int)$_GET['delete'],$uid]);flash('Catatan dihapus.');header('Location: notes.php');exit;}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM notes WHERE id=? AND user_id=?');$s->execute([(int)$_GET['edit'],$uid]);$edit=$s->fetch();}
$s=$pdo->prepare('SELECT * FROM notes WHERE user_id=? ORDER BY created_at DESC');$s->execute([$uid]);$notes=$s->fetchAll();$pageTitle='Catatan';require 'includes/header.php';
?>
<div class="page-heading"><div><p class="eyebrow">SIMPAN IDE DAN INFORMASI</p><h1>Catatan</h1><p class="muted">Tempat sederhana untuk menyimpan hal-hal penting.</p></div></div>
<div class="content-split"><form class="panel compact-form" method="post"><h2><?= $edit?'Edit catatan':'Tulis catatan' ?></h2><input type="hidden" name="id" value="<?= e($edit['id']??'') ?>"><label>Judul catatan</label><input name="judul_catatan" required maxlength="150" value="<?= e($edit['judul_catatan']??'') ?>" placeholder="Judul catatan"><label>Isi catatan</label><textarea name="isi_catatan" rows="8" required placeholder="Tulis catatanmu di sini..."><?= e($edit['isi_catatan']??'') ?></textarea><button class="btn btn-primary btn-full">Simpan Catatan</button><?php if($edit): ?><a class="text-link center-link" href="notes.php">Batal edit</a><?php endif; ?></form>
<div class="note-grid"><?php if(!$notes): ?><div class="panel empty-state"><div class="empty-icon">▤</div><h3>Belum ada catatan</h3><p>Ide pentingmu bisa dimulai dari sini.</p></div><?php else: foreach($notes as $n): ?><article class="note-card"><div class="note-pin">✦</div><h3><?= e($n['judul_catatan']) ?></h3><p><?= nl2br(e($n['isi_catatan'])) ?></p><small><?= e(date('d M Y',strtotime($n['created_at']))) ?></small><div class="note-actions"><a href="notes.php?edit=<?= $n['id'] ?>">Edit</a><a class="danger-text" href="notes.php?delete=<?= $n['id'] ?>" onclick="return confirm('Hapus catatan ini?')">Hapus</a></div></article><?php endforeach; endif; ?></div></div>
<?php require 'includes/footer.php'; ?>
